-- Nach 0-gemeinsam.sql ausführen. Mehrfach ausführbar, gespielte Runden bleiben erhalten.

begin;

delete from public.massnahmen where thema_id = 45;
delete from public.abdeckung where thema_id = 45;
delete from public.pruef_einheiten where thema_id = 45;

-- Lösungswege für die Forderungskarte (ohne Punkte). Upsert, damit gespeicherte Forderungen ihren Verweis behalten.
insert into public.instrumente (id, thema_id, name, begruendung, evidenz, beleg_studie_url, ebene, entspricht, ki_entwurf, entwurf_herkunft, nebenwirkungen) values
  (10881, 45, 'Generelles Tempolimit auf Autobahnen einführen (Bund)', 'Laut UBA spart Tempo 130 etwa 1,3-2,0 Mio. t, Tempo 120 mit 80 außerorts rund 6,6 Mio. t CO2-Äq. pro Jahr; per Gesetz sofort umsetzbar und kostengünstig, deckt aber nur einen Teil der Verkehrslücke.', 'belegt', 'https://www.umweltbundesamt.de/themen/verkehr/nachhaltige-mobilitaet/tempolimit', 'bund', null, true, 'blind', '[{"bereich":"wirtschaft","richtung":"nachteil","text":"Ein allgemeines Tempolimit verursacht laut einer älteren UBA-Studie Kosten durch höheren Zeitbedarf der Pkw-Fahrer bei gegebener Wegstrecke.","quelle_url":"https://www.umweltbundesamt.de/system/files/medien/publikation/long/3136.pdf","belegstufe":"A"},{"bereich":"grundrechte","richtung":"vorteil","text":"Ein Tempolimit kann laut Umweltbundesamt die Zahl schwerer Unfälle und die Schwere der Verletzungen verringern.","quelle_url":"https://www.umweltbundesamt.de/themen/verkehr/nachhaltige-mobilitaet/tempolimit","belegstufe":"A"}]'::jsonb),
  (10882, 45, 'Generelles Tempolimit auf Autobahnen ablehnen (Bund)', 'Hält den Status quo; die laut UBA mögliche Minderung von 1,3 bis 6,6 Mio. t CO2-Äq. pro Jahr bleibt ungenutzt, die Verkehrsemissionen sinken dadurch nicht.', 'belegt', 'https://www.umweltbundesamt.de/themen/verkehr/nachhaltige-mobilitaet/tempolimit', 'bund', null, true, 'blind', '[{"bereich":"wirtschaft","richtung":"vorteil","text":"Ohne Tempolimit entfällt der höhere Zeitbedarf der Pkw-Fahrer bei gegebener Wegstrecke, den laut einer älteren UBA-Studie ein allgemeines Tempolimit verursacht.","quelle_url":"https://www.umweltbundesamt.de/system/files/medien/publikation/long/3136.pdf","belegstufe":"A"},{"bereich":"grundrechte","richtung":"nachteil","text":"Ohne Tempolimit bleibt die Verringerung schwerer Unfälle und der Verletzungsschwere ungenutzt, die laut Umweltbundesamt ein Tempolimit bringen kann.","quelle_url":"https://www.umweltbundesamt.de/themen/verkehr/nachhaltige-mobilitaet/tempolimit","belegstufe":"A"}]'::jsonb),
  (10883, 45, 'CO2-Preis und klimabezogene Abgaben im Verkehr senken oder abschaffen (Bund)', 'Studien zeigen, dass CO2-Preise Emissionen auch bei niedrigen Preisen senken; ihr Abbau schwächt diesen Anreiz. Rechtlich national möglich, ab dem EU-Emissionshandel für Verkehr und Wärme aber begrenzt.', 'belegt', 'https://strathprints.strath.ac.uk/72023', 'bund', null, true, 'blind', '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Der nationale Emissionshandel für Wärme und Verkehr brachte 2025 rund 16 Mrd. Euro für den Klima- und Transformationsfonds; das sind nicht die Kosten dieses Wegs.","quelle_url":"https://dehst.de/SharedDocs/Pressemitteilungen/DE/2026-001-Emissionshandel-21-Milliarden-Euro.html","belegstufe":"A"},{"bereich":"verteilung","richtung":"gemischt","text":"Die CO2-Bepreisung von Wärme und Verkehr belastet Haushalte 2024 mit 8,5 Mrd. Euro, Geringverdienende relativ stärker; Grundsicherung und Wohngeld gleichen das weitgehend aus.","quelle_url":"https://www.umweltbundesamt.de/system/files/medien/11850/publikationen/72_2025_cc_bf.pdf","belegstufe":"A"}]'::jsonb),
  (10884, 45, 'Straßenausbau, Fahrspuren und Straßenfinanzierung stärken (Bund)', 'Mehr Straßenkapazität senkt keine Emissionen; Studien zu induziertem Verkehr zeigen eher Mehrverkehr, die Größe des Effekts schwankt aber stark je nach Lage und Stauniveau.', 'gemischt', null, 'bund', null, true, 'blind', '[{"bereich":"wirtschaft","richtung":"vorteil","text":"Straßenprojekte des Bundesverkehrswegeplans 2030 bringen laut Gesamtplanbewertung vor allem Zeitgewinne, Kosteneinsparungen und mehr Verkehrssicherheit für Verkehrsteilnehmer.","quelle_url":"https://www.bmv.de/SharedDocs/DE/Anlage/G/BVWP/bvwp-2030-kabinettsplan.pdf?__blob=publicationFile","belegstufe":"A"},{"bereich":"umwelt","richtung":"nachteil","text":"Beim Bundesverkehrswegeplan 2030 ist die Flächeninanspruchnahme der Straße je investiertem Euro fast fünfmal so groß wie bei der Schiene und zwölfmal so groß wie bei der Wasserstraße.","quelle_url":"https://www.bmv.de/SharedDocs/DE/Anlage/G/BVWP/bvwp-2030-kabinettsplan.pdf?__blob=publicationFile","belegstufe":"A"}]'::jsonb),
  (10885, 45, 'Radwegenetz und Mobilstationen ausbauen (Bund)', 'Neue Radwege werden genutzt, ersetzen laut Studien aber oft nur wenige Autofahrten; ohne begleitende Maßnahmen bleibt die CO2-Wirkung klein. Bund kann über Förderprogramme beitragen.', 'gemischt', null, 'bund', null, true, 'blind', '[{"bereich":"grundrechte","richtung":"vorteil","text":"Regelmäßiges Radfahren erhöht laut einer vom Umweltbundesamt genannten Untersuchung die Lebenserwartung um 3 bis 14 Monate.","quelle_url":"https://www.umweltbundesamt.de/themen/verkehr/nachhaltige-mobilitaet/radverkehr","belegstufe":"A"}]'::jsonb),
  (10886, 45, 'Neuzulassung nur emissionsfreier Pkw ab 2035 beibehalten (Bund)', 'EU-Flottengrenzwerte haben die Neuwagen-Emissionen 2019-2023 um rund 28 % gesenkt; die Wirkung auf den Bestand kommt aber verzögert, und die Regel hängt von EU-Entscheidungen ab.', 'belegt', 'https://www.eea.europa.eu/data-and-maps/indicators/average-co2-emissions-from-motor-vehicles-1/assessment', 'bund', null, true, 'blind', '[{"bereich":"umwelt","richtung":"vorteil","text":"Elektroautos stoßen laut Umweltbundesamt lokal keine Abgasschadstoffe aus und verringern die Lärmbelastung.","quelle_url":"https://www.umweltbundesamt.de/umwelttipps-fuer-den-alltag/beim-autokauf-elektroautos-bevorzugen-auf-geringen","belegstufe":"A"}]'::jsonb),
  (10887, 45, 'Verbrenner-Aus 2035 und Flottengrenzwerte aufheben (Bund)', 'Flottengrenzwerte haben die Neuwagen-Emissionen nachweislich gesenkt; ihre Aufhebung bremst die Minderung. Zudem kann Deutschland die EU-Verordnung nicht allein ändern.', 'belegt', 'https://www.eea.europa.eu/data-and-maps/indicators/average-co2-emissions-from-motor-vehicles-1/assessment', 'bund', null, true, 'blind', '[]'::jsonb),
  (10888, 45, 'Güterverkehr von der Straße auf Schiene und Wasserstraße verlagern (Bund)', 'Schiene verursacht je Tonnenkilometer deutlich weniger Emissionen; trotz Förderung stagniert der Kombiverkehr aber, weil er privat rund 28 % teurer ist. Ausbau braucht Jahre.', 'gemischt', 'https://repositum.tuwien.at/handle/20.500.12708/189196?mode=full', 'bund', null, true, 'blind', '[{"bereich":"umwelt","richtung":"gemischt","text":"Je Tonnenkilometer stießen Güterbahnen 2022 rund 0,032 g Stickoxide aus, Lkw 0,198 g, Binnenschiffe 0,415 g; bei Luftschadstoffen hat nur die Schiene einen Vorteil.","quelle_url":"https://www.umweltbundesamt.de/system/files/medien/479/publikationen/schwere_lasten_grosse_aufgabe_ein_ziel_v5_240822_bf.pdf","belegstufe":"A"},{"bereich":"grundrechte","richtung":"nachteil","text":"Der Schienengüterverkehr ist besonders laut und fährt vor allem nachts, wenn Anwohner besonders lärmempfindlich sind (Umweltbundesamt, 2017).","quelle_url":"https://www.umweltbundesamt.de/presse/pressemitteilungen/jeder-fuenfte-deutsche-leidet-unter-schienenlaerm","belegstufe":"A"}]'::jsonb),
  (10889, 45, 'Dünge-Vorgaben und Stoffstrombilanz lockern oder abschaffen (Bund)', 'Weniger Kontrolle der Stickstoffüberschüsse senkt kein Lachgas, sondern riskiert mehr; der Nutzen der Stoffstrombilanz für die Beratung ist allerdings umstritten. Lockerungen stoßen an die EU-Nitratrichtlinie.', 'gemischt', null, 'bund', null, true, 'blind', '[{"bereich":"aufwand","richtung":"vorteil","text":"Die Streichung der Stoffstrombilanz senkt den Erfüllungsaufwand um jährlich 18,1 Millionen Euro.","quelle_url":"https://dserver.bundestag.de/brd/2026/0251-26.pdf","belegstufe":"A"},{"bereich":"umwelt","richtung":"nachteil","text":"An landwirtschaftlich geprägten Grundwassermessstellen überschreiten 25,6 % den Nitrat-Grenzwert von 50 mg/l; weniger Kontrolle der Überschüsse riskiert mehr.","quelle_url":"https://www.umweltbundesamt.de/daten/wasser/grundwasserbeschaffenheit","belegstufe":"A"}]'::jsonb),
  (10890, 45, 'Sektorziele und verbindliche Nachsteuerung im Klimaschutzgesetz stärken (Bund)', 'Der Expertenrat sah im Wegfall sektoraler Nachsteuerung eine erhöhte Gefahr der Zielverfehlung; zugleich wurden Sektorziele früher trotz Sofortprogrammen verfehlt. Per Gesetzesänderung schnell möglich.', 'gemischt', 'https://www.aerzteblatt.de/news/expertenrat-sieht-ampelplaene-zum-klimaschutzgesetz-kritisch-bb9035c9-d676-4e4e-88fe-42c073c03dc9', 'bund', null, true, 'blind', '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Das Sofortprogramm 2020 für den Gebäudesektor sah zusätzliche Mittel von 5,8 Mrd. Euro für die Gebäudeförderung 2021 vor; das sind nicht die Kosten dieses Wegs.","quelle_url":"https://expertenrat-klima.de/fileadmin/ERK/Pressemitteilungen_Meldungen/ERK2021_Pruefbericht-Sofortprogramm-Gebaeudesektor_Pressemitteilung.pdf","belegstufe":"A"}]'::jsonb),
  (10891, 45, 'EU-Emissionshandel mit sinkender Obergrenze auf alle Sektoren ausweiten (Bund)', 'Der EU-Emissionshandel hat Emissionen nachweislich gesenkt, eine Obergrenze sichert die Gesamtmenge; Sektorverfehlungen werden aber nicht behoben, und die Ausweitung hängt von EU-Entscheidungen ab.', 'belegt', 'https://strathprints.strath.ac.uk/72023', 'bund', null, true, 'blind', '[{"bereich":"haushalt","richtung":"vorteil","text":"Zum Vergleich: Der nationale Emissionshandel für Wärme und Verkehr, die bisher nicht im EU-Emissionshandel liegen, brachte 2025 rund 16 Mrd. Euro; das sind nicht die Erlöse dieses Wegs.","quelle_url":"https://dehst.de/SharedDocs/Pressemitteilungen/DE/2026-001-Emissionshandel-21-Milliarden-Euro.html","belegstufe":"A"},{"bereich":"verteilung","richtung":"nachteil","text":"Zum Vergleich: Die CO2-Bepreisung von Wärme und Verkehr (nationaler Emissionshandel) belastete 2024 private Haushalte mit 8,5 Mrd. Euro und Unternehmen mit 3,8 Mrd. Euro; nicht die Kosten dieses Wegs.","quelle_url":"https://www.umweltbundesamt.de/system/files/medien/11850/publikationen/72_2025_cc_bf.pdf","belegstufe":"A"}]'::jsonb)
