delete from public.instrumente where thema_id = 45 and id not in (10881, 10882, 10883, 10884, 10885, 10886, 10887, 10888, 10889, 10890, 10891);

insert into public.massnahmen (id, thema_id, partei_id, land, beschreibung, ursachen_ids, instrument_id, wirksamkeit, umsetzbarkeit,
  rollen_modifikator, begruendung, beleg_programm_url, beleg_studie_url, evidenz, stand, geprueft, ki_entwurf, entwurf_herkunft, nebenwirkungen) values
  (10892, 45, 11, null, 'Neue Radwege, Ausbau des Radnetzes und Mobilstationen an Verkehrsknotenpunkten, um Rad und Verkehrsmittel zu verknüpfen', '{4501}', 10885, 1, 2, null, 'Neue Radwege werden genutzt, ersetzen laut Studien aber oft nur wenige Autofahrten; ohne begleitende Maßnahmen bleibt die CO2-Wirkung klein. Bund kann über Förderprogramme beitragen.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=75', null, 'gemischt', '2026-10-22', false, true, 'blind', '[{"bereich":"grundrechte","richtung":"vorteil","text":"Regelmäßiges Radfahren erhöht laut einer vom Umweltbundesamt genannten Untersuchung die Lebenserwartung um 3 bis 14 Monate.","quelle_url":"https://www.umweltbundesamt.de/themen/verkehr/nachhaltige-mobilitaet/radverkehr","belegstufe":"A"}]'::jsonb),
  (10893, 45, 11, null, 'Verbrenner-Verbot rückgängig machen, Flottengrenzwerte überprüfen und Strafzahlungen verhindern', '{4501}', 10887, 0, 1, null, 'Flottengrenzwerte haben die Neuwagen-Emissionen nachweislich gesenkt; ihre Aufhebung bremst die Minderung. Zudem kann Deutschland die EU-Verordnung nicht allein ändern.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=74', 'https://www.eea.europa.eu/data-and-maps/indicators/average-co2-emissions-from-motor-vehicles-1/assessment', 'belegt', '2026-10-22', false, true, 'blind', '[]'::jsonb),
  (10894, 45, 11, null, 'Generelles Tempolimit auf Autobahnen und Fahrverbote für Innenstädte ablehnen', '{4501}', 10882, 0, 3, null, 'Hält den Status quo; die laut UBA mögliche Minderung von 1,3 bis 6,6 Mio. t CO2-Äq. pro Jahr bleibt ungenutzt, die Verkehrsemissionen sinken dadurch nicht.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=74', 'https://www.umweltbundesamt.de/themen/verkehr/nachhaltige-mobilitaet/tempolimit', 'belegt', '2026-10-22', false, true, 'blind', '[{"bereich":"wirtschaft","richtung":"vorteil","text":"Ohne Tempolimit entfällt der höhere Zeitbedarf der Pkw-Fahrer bei gegebener Wegstrecke, den laut einer älteren UBA-Studie ein allgemeines Tempolimit verursacht.","quelle_url":"https://www.umweltbundesamt.de/system/files/medien/publikation/long/3136.pdf","belegstufe":"A"},{"bereich":"grundrechte","richtung":"nachteil","text":"Ohne Tempolimit bleibt die Verringerung schwerer Unfälle und der Verletzungsschwere ungenutzt, die laut Umweltbundesamt ein Tempolimit bringen kann.","quelle_url":"https://www.umweltbundesamt.de/themen/verkehr/nachhaltige-mobilitaet/tempolimit","belegstufe":"A"}]'::jsonb),
  (10895, 45, 11, null, 'Belastung des Transportgewerbes durch CO2-Preis und CO2-Zuschlag senken', '{4501}', 10883, 0, 2, null, 'Studien zeigen, dass CO2-Preise Emissionen auch bei niedrigen Preisen senken; ihr Abbau schwächt diesen Anreiz. Rechtlich national möglich, ab dem EU-Emissionshandel für Verkehr und Wärme aber begrenzt.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=74', 'https://strathprints.strath.ac.uk/72023', 'belegt', '2026-10-22', false, true, 'blind', '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Der nationale Emissionshandel für Wärme und Verkehr brachte 2025 rund 16 Mrd. Euro für den Klima- und Transformationsfonds; das sind nicht die Kosten dieses Wegs.","quelle_url":"https://dehst.de/SharedDocs/Pressemitteilungen/DE/2026-001-Emissionshandel-21-Milliarden-Euro.html","belegstufe":"A"},{"bereich":"verteilung","richtung":"gemischt","text":"Die CO2-Bepreisung von Wärme und Verkehr belastet Haushalte 2024 mit 8,5 Mrd. Euro, Geringverdienende relativ stärker; Grundsicherung und Wohngeld gleichen das weitgehend aus.","quelle_url":"https://www.umweltbundesamt.de/system/files/medien/11850/publikationen/72_2025_cc_bf.pdf","belegstufe":"A"}]'::jsonb),
  (10896, 45, 11, null, 'Auskömmliche Finanzierung von Autobahnen, Brücken und Straßeninfrastruktur (Erhalt und Neubau)', '{4501}', 10884, 0, 2, null, 'Mehr Straßenkapazität senkt keine Emissionen; Studien zu induziertem Verkehr zeigen eher Mehrverkehr, die Größe des Effekts schwankt aber stark je nach Lage und Stauniveau.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=74', null, 'gemischt', '2026-10-22', false, true, 'blind', '[{"bereich":"wirtschaft","richtung":"vorteil","text":"Straßenprojekte des Bundesverkehrswegeplans 2030 bringen laut Gesamtplanbewertung vor allem Zeitgewinne, Kosteneinsparungen und mehr Verkehrssicherheit für Verkehrsteilnehmer.","quelle_url":"https://www.bmv.de/SharedDocs/DE/Anlage/G/BVWP/bvwp-2030-kabinettsplan.pdf?__blob=publicationFile","belegstufe":"A"},{"bereich":"umwelt","richtung":"nachteil","text":"Beim Bundesverkehrswegeplan 2030 ist die Flächeninanspruchnahme der Straße je investiertem Euro fast fünfmal so groß wie bei der Schiene und zwölfmal so groß wie bei der Wasserstraße.","quelle_url":"https://www.bmv.de/SharedDocs/DE/Anlage/G/BVWP/bvwp-2030-kabinettsplan.pdf?__blob=publicationFile","belegstufe":"A"}]'::jsonb),
  (10897, 45, 11, null, 'Kosten energetischer Sanierungen von der Erbschaft- und Schenkungsteuer abzugsfähig machen', '{4502}', null, 1, 2, null, 'Schafft einen Sanierungsanreiz beim Erben oder Schenken, betrifft aber nur wenige Fälle und vor allem Vermögende; Länder erhalten die Steuer, daher Zustimmung des Bundesrats nötig.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=73', null, 'offen', '2026-10-22', false, true, 'blind', '[{"bereich":"verteilung","richtung":"gemischt","text":"Etwa die Hälfte der Erbschaften und Schenkungen liegt unter 50.000 Euro, Übertragungen über 500.000 Euro erhalten 1,5 Prozent der Begünstigten; ein Abzug setzt an dieser Verteilung an.","quelle_url":"https://www.diw.de/de/diw_01.c.524604.de/publikationen/wochenberichte/2016_03_1/hohe_erbschaftswelle__niedriges_erbschaftsteueraufkommen.html","belegstufe":"B"}]'::jsonb),
  (10898, 45, 11, null, 'Gegen eine Reduktion oder Quoten für Tierhaltung, Fortbestand der Kombihaltung', '{4503}', null, 0, 3, null, 'Tierhaltung ist die größte Quelle der Agraremissionen; wer jede Bestandsreduktion ablehnt, lässt diesen Hebel ungenutzt. Als Status quo ohne Aufwand umsetzbar.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=37', 'https://www.umweltbundesamt.de/tags/tierbestand', 'belegt', '2026-10-22', false, true, 'blind', '[{"bereich":"umwelt","richtung":"nachteil","text":"Rund 70 Prozent der Ammoniak-Emissionen stammen aus der Tierhaltung; Ammoniak schädigt Land- und Wasserökosysteme erheblich.","quelle_url":"https://www.umweltbundesamt.de/themen/boden-landwirtschaft/umweltbelastungen-der-landwirtschaft/ammoniak-geruch-staub","belegstufe":"A"}]'::jsonb),
  (10899, 45, 11, null, 'Stoffstrombilanz im Düngerecht abschaffen', '{4503}', 10889, 0, 2, null, 'Weniger Kontrolle der Stickstoffüberschüsse senkt kein Lachgas, sondern riskiert mehr; der Nutzen der Stoffstrombilanz für die Beratung ist allerdings umstritten. Lockerungen stoßen an die EU-Nitratrichtlinie.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=36', null, 'gemischt', '2026-10-22', false, true, 'blind', '[{"bereich":"aufwand","richtung":"vorteil","text":"Die Streichung der Stoffstrombilanz senkt den Erfüllungsaufwand um jährlich 18,1 Millionen Euro.","quelle_url":"https://dserver.bundestag.de/brd/2026/0251-26.pdf","belegstufe":"A"},{"bereich":"umwelt","richtung":"nachteil","text":"An landwirtschaftlich geprägten Grundwassermessstellen überschreiten 25,6 % den Nitrat-Grenzwert von 50 mg/l; weniger Kontrolle der Überschüsse riskiert mehr.","quelle_url":"https://www.umweltbundesamt.de/daten/wasser/grundwasserbeschaffenheit","belegstufe":"A"}]'::jsonb),
  (10900, 45, 11, null, 'Emissionshandel schrittweise auf alle Sektoren mit energiebedingten Emissionen ausweiten', '{4504}', 10891, 2, 1, null, 'Der EU-Emissionshandel hat Emissionen nachweislich gesenkt, eine Obergrenze sichert die Gesamtmenge; Sektorverfehlungen werden aber nicht behoben, und die Ausweitung hängt von EU-Entscheidungen ab.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=24', 'https://strathprints.strath.ac.uk/72023', 'belegt', '2026-10-22', false, true, 'blind', '[{"bereich":"haushalt","richtung":"vorteil","text":"Zum Vergleich: Der nationale Emissionshandel für Wärme und Verkehr, die bisher nicht im EU-Emissionshandel liegen, brachte 2025 rund 16 Mrd. Euro; das sind nicht die Erlöse dieses Wegs.","quelle_url":"https://dehst.de/SharedDocs/Pressemitteilungen/DE/2026-001-Emissionshandel-21-Milliarden-Euro.html","belegstufe":"A"},{"bereich":"verteilung","richtung":"nachteil","text":"Zum Vergleich: Die CO2-Bepreisung von Wärme und Verkehr (nationaler Emissionshandel) belastete 2024 private Haushalte mit 8,5 Mrd. Euro und Unternehmen mit 3,8 Mrd. Euro; nicht die Kosten dieses Wegs.","quelle_url":"https://www.umweltbundesamt.de/system/files/medien/11850/publikationen/72_2025_cc_bf.pdf","belegstufe":"A"}]'::jsonb),
  (10901, 45, 12, null, 'Tempolimit auf Bundesautobahnen einführen.', '{4501}', 10881, 2, 3, null, 'Laut UBA spart Tempo 130 etwa 1,3-2,0 Mio. t, Tempo 120 mit 80 außerorts rund 6,6 Mio. t CO2-Äq. pro Jahr; per Gesetz sofort umsetzbar und kostengünstig, deckt aber nur einen Teil der Verkehrslücke.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=36', 'https://www.umweltbundesamt.de/themen/verkehr/nachhaltige-mobilitaet/tempolimit', 'belegt', '2026-10-22', false, true, 'blind', '[{"bereich":"wirtschaft","richtung":"nachteil","text":"Ein allgemeines Tempolimit verursacht laut einer älteren UBA-Studie Kosten durch höheren Zeitbedarf der Pkw-Fahrer bei gegebener Wegstrecke.","quelle_url":"https://www.umweltbundesamt.de/system/files/medien/publikation/long/3136.pdf","belegstufe":"A"},{"bereich":"grundrechte","richtung":"vorteil","text":"Ein Tempolimit kann laut Umweltbundesamt die Zahl schwerer Unfälle und die Schwere der Verletzungen verringern.","quelle_url":"https://www.umweltbundesamt.de/themen/verkehr/nachhaltige-mobilitaet/tempolimit","belegstufe":"A"}]'::jsonb),
  (10902, 45, 12, null, 'Verkehr von der Straße auf Schiene und Wasserstraße lenken.', '{4501}', 10888, 1, 2, null, 'Schiene verursacht je Tonnenkilometer deutlich weniger Emissionen; trotz Förderung stagniert der Kombiverkehr aber, weil er privat rund 28 % teurer ist. Ausbau braucht Jahre.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=34', 'https://repositum.tuwien.at/handle/20.500.12708/189196?mode=full', 'gemischt', '2026-10-22', false, true, 'blind', '[{"bereich":"umwelt","richtung":"gemischt","text":"Je Tonnenkilometer stießen Güterbahnen 2022 rund 0,032 g Stickoxide aus, Lkw 0,198 g, Binnenschiffe 0,415 g; bei Luftschadstoffen hat nur die Schiene einen Vorteil.","quelle_url":"https://www.umweltbundesamt.de/system/files/medien/479/publikationen/schwere_lasten_grosse_aufgabe_ein_ziel_v5_240822_bf.pdf","belegstufe":"A"},{"bereich":"grundrechte","richtung":"nachteil","text":"Der Schienengüterverkehr ist besonders laut und fährt vor allem nachts, wenn Anwohner besonders lärmempfindlich sind (Umweltbundesamt, 2017).","quelle_url":"https://www.umweltbundesamt.de/presse/pressemitteilungen/jeder-fuenfte-deutsche-leidet-unter-schienenlaerm","belegstufe":"A"}]'::jsonb),
  (10903, 45, 12, null, 'Luftverkehrsteuer in eine EU-Klimaabgabe umwandeln, die alle Airlines zahlen.', '{4501}', null, 1, 1, null, 'Eine EU-weite Klimaabgabe für alle Airlines könnte Flugnachfrage dämpfen; sie erfordert aber Einigung in der EU und mit Drittstaaten, und die Wirkung auf nationale Emissionen ist gering.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=37', null, 'offen', '2026-10-22', false, true, 'blind', '[{"bereich":"haushalt","richtung":"gemischt","text":"Zum Vergleich: Für die Luftverkehrsteuer, die dieser Weg ersetzt, wurden 2025 rund 2,1 Mrd. Euro angemeldet; das sind nicht die Kosten dieses Wegs.","quelle_url":"https://www.destatis.de/DE/Themen/Staat/Steuern/Weitere-Steuern/luftverkehrsteuer.html","belegstufe":"A"}]'::jsonb),
  (10904, 45, 12, null, 'Flottengrenzwerte mit der EU-Kommission beibehalten, aber den Weg dorthin pragmatischer gestalten.', '{4501}', null, 1, 1, null, 'Die Ziele bleiben, ein „pragmatischerer Weg“ dürfte die Minderung bis 2030 aber verlangsamen; abhängig von Verhandlungen auf EU-Ebene.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=7', null, 'gemischt', '2026-10-22', false, true, 'blind', '[]'::jsonb),
  (10905, 45, 12, null, 'Befristeter Steuerabzug beim Kauf eines in Deutschland produzierten E-Autos, auch beim privaten Neuwagenkauf.', '{4501}', null, 1, 0, null, 'Kaufanreize beschleunigen E-Auto-Käufe, haben aber hohe Mitnahmeeffekte; die Bindung an Produktion in Deutschland benachteiligt Waren aus anderen EU-Staaten und ist EU-rechtlich kaum haltbar.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=7', null, 'gemischt', '2026-10-22', false, true, 'blind', '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Die frühere Kaufprämie Umweltbonus hatte 2016 bis 2023 bewilligte Bundesmittel von 10,17 Mrd. Euro; das sind nicht die Kosten dieses Wegs.","quelle_url":"https://technopolis-group.com/wp-content/uploads/2024/11/EB_Evaluation_Umweltbonus.pdf","belegstufe":"B"},{"bereich":"verteilung","richtung":"nachteil","text":"Bei der früheren Kaufprämie Umweltbonus hatten rund 60 % der Geförderten über 4.500 Euro und rund 30 % über 6.000 Euro Haushaltsnettoeinkommen im Monat.","quelle_url":"https://technopolis-group.com/wp-content/uploads/2024/11/EB_Evaluation_Umweltbonus.pdf","belegstufe":"B"}]'::jsonb),
  (10906, 45, 12, null, 'Straßen-Engpässe weiterhin beseitigen.', '{4501}', 10884, 0, 2, null, 'Mehr Straßenkapazität senkt keine Emissionen; Studien zu induziertem Verkehr zeigen eher Mehrverkehr, die Größe des Effekts schwankt aber stark je nach Lage und Stauniveau.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=36', null, 'gemischt', '2026-10-22', false, true, 'blind', '[{"bereich":"wirtschaft","richtung":"vorteil","text":"Straßenprojekte des Bundesverkehrswegeplans 2030 bringen laut Gesamtplanbewertung vor allem Zeitgewinne, Kosteneinsparungen und mehr Verkehrssicherheit für Verkehrsteilnehmer.","quelle_url":"https://www.bmv.de/SharedDocs/DE/Anlage/G/BVWP/bvwp-2030-kabinettsplan.pdf?__blob=publicationFile","belegstufe":"A"},{"bereich":"umwelt","richtung":"nachteil","text":"Beim Bundesverkehrswegeplan 2030 ist die Flächeninanspruchnahme der Straße je investiertem Euro fast fünfmal so groß wie bei der Schiene und zwölfmal so groß wie bei der Wasserstraße.","quelle_url":"https://www.bmv.de/SharedDocs/DE/Anlage/G/BVWP/bvwp-2030-kabinettsplan.pdf?__blob=publicationFile","belegstufe":"A"}]'::jsonb),
  (10907, 45, 12, null, 'Programm „Jung kauft Alt“ ausbauen, mit Zuschüssen zur energetischen Sanierung.', '{4502}', null, 1, 3, null, 'Zuschüsse beim Kauf alter Häuser verbinden Eigentumserwerb mit Sanierung; das Programm ist klein, die zusätzliche Minderung begrenzt.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=22', null, 'offen', '2026-10-22', false, true, 'blind', '[]'::jsonb),
  (10908, 45, 12, null, 'Agrarförderung ab der neuen Förderperiode stärker an Betriebe mit Klimaschutzmaßnahmen knüpfen.', '{4503}', null, 1, 1, null, 'Der EU-Rechnungshof fand, dass Klimaausgaben der GAP die Agraremissionen bisher nicht gesenkt haben; gezieltere Bindung könnte helfen, hängt aber von EU-Entscheidungen ab.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=54', null, 'gemischt', '2026-10-22', false, true, 'blind', '[]'::jsonb),
  (10909, 45, 13, null, 'Ab 2035 nur noch klimaneutrale Antriebe neu zulassen.', '{4501}', 10886, 2, 1, null, 'EU-Flottengrenzwerte haben die Neuwagen-Emissionen 2019-2023 um rund 28 % gesenkt; die Wirkung auf den Bestand kommt aber verzögert, und die Regel hängt von EU-Entscheidungen ab.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=25', 'https://www.eea.europa.eu/data-and-maps/indicators/average-co2-emissions-from-motor-vehicles-1/assessment', 'belegt', '2026-10-22', false, true, 'blind', '[{"bereich":"umwelt","richtung":"vorteil","text":"Elektroautos stoßen laut Umweltbundesamt lokal keine Abgasschadstoffe aus und verringern die Lärmbelastung.","quelle_url":"https://www.umweltbundesamt.de/umwelttipps-fuer-den-alltag/beim-autokauf-elektroautos-bevorzugen-auf-geringen","belegstufe":"A"}]'::jsonb),
  (10910, 45, 13, null, 'Verlagerung von Straßentransport auf die Schiene fördern und Kapazitäten im Kombiverkehr ausbauen.', '{4501}', 10888, 1, 2, null, 'Schiene verursacht je Tonnenkilometer deutlich weniger Emissionen; trotz Förderung stagniert der Kombiverkehr aber, weil er privat rund 28 % teurer ist. Ausbau braucht Jahre.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=50', 'https://repositum.tuwien.at/handle/20.500.12708/189196?mode=full', 'gemischt', '2026-10-22', false, true, 'blind', '[{"bereich":"umwelt","richtung":"gemischt","text":"Je Tonnenkilometer stießen Güterbahnen 2022 rund 0,032 g Stickoxide aus, Lkw 0,198 g, Binnenschiffe 0,415 g; bei Luftschadstoffen hat nur die Schiene einen Vorteil.","quelle_url":"https://www.umweltbundesamt.de/system/files/medien/479/publikationen/schwere_lasten_grosse_aufgabe_ein_ziel_v5_240822_bf.pdf","belegstufe":"A"},{"bereich":"grundrechte","richtung":"nachteil","text":"Der Schienengüterverkehr ist besonders laut und fährt vor allem nachts, wenn Anwohner besonders lärmempfindlich sind (Umweltbundesamt, 2017).","quelle_url":"https://www.umweltbundesamt.de/presse/pressemitteilungen/jeder-fuenfte-deutsche-leidet-unter-schienenlaerm","belegstufe":"A"}]'::jsonb),
  (10911, 45, 13, null, 'Privilegien für Privatjets abschaffen, um diese klimaschädliche Fortbewegungsart zu reduzieren.', '{4501}', null, 1, 2, null, 'Privatjets sind je Person sehr emissionsintensiv, machen aber nur einen kleinen Teil der Verkehrsemissionen aus; welche Privilegien wegfallen, bleibt unklar, teils EU-Recht.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=47', null, 'offen', '2026-10-22', false, true, 'blind', '[]'::jsonb),
  (10912, 45, 13, null, 'Generelles Tempolimit von 130 km/h auf Autobahnen, das die Partei als überfällig ansieht.', '{4501}', 10881, 2, 3, null, 'Laut UBA spart Tempo 130 etwa 1,3-2,0 Mio. t, Tempo 120 mit 80 außerorts rund 6,6 Mio. t CO2-Äq. pro Jahr; per Gesetz sofort umsetzbar und kostengünstig, deckt aber nur einen Teil der Verkehrslücke.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=48', 'https://www.umweltbundesamt.de/themen/verkehr/nachhaltige-mobilitaet/tempolimit', 'belegt', '2026-10-22', false, true, 'blind', '[{"bereich":"wirtschaft","richtung":"nachteil","text":"Ein allgemeines Tempolimit verursacht laut einer älteren UBA-Studie Kosten durch höheren Zeitbedarf der Pkw-Fahrer bei gegebener Wegstrecke.","quelle_url":"https://www.umweltbundesamt.de/system/files/medien/publikation/long/3136.pdf","belegstufe":"A"},{"bereich":"grundrechte","richtung":"vorteil","text":"Ein Tempolimit kann laut Umweltbundesamt die Zahl schwerer Unfälle und die Schwere der Verletzungen verringern.","quelle_url":"https://www.umweltbundesamt.de/themen/verkehr/nachhaltige-mobilitaet/tempolimit","belegstufe":"A"}]'::jsonb),
  (10913, 45, 13, null, 'Nachhaltige Kraftstoffe aus erneuerbaren Energien für den Luft- und Schiffsverkehr unterstützen.', '{4501}', null, 1, 2, null, 'E-Kerosin kann Luftverkehr dekarbonisieren, kostet laut ICCT aber ein Vielfaches fossilen Kerosins und ist vor 2050 nicht wettbewerbsfähig; bis 2030 kleine Mengen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=47', 'https://trid.trb.org/View/1925817', 'gemischt', '2026-10-22', false, true, 'blind', '[]'::jsonb),
  (10914, 45, 13, null, 'Förderung für energetische Sanierungen stärker nach Einkommen und eingesparter Energie staffeln.', '{4502}', null, 2, 3, null, 'Sanierungsförderung spart laut Evaluation des Förderjahres 2021 rund 1,7 Mio. t CO2-Äq. pro Jahr; Staffelung nach Einsparung erhöht die Zielgenauigkeit, Mitnahmeeffekte bleiben möglich.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=72', 'https://www.solarserver.de/2023/06/15/erste-externe-evaluation-der-beg-foerderung-vorgelegt/', 'belegt', '2026-10-22', false, true, 'blind', '[{"bereich":"verteilung","richtung":"gemischt","text":"Bisher nutzen vor allem Haushalte mit über 5.000 Euro Nettoeinkommen die BEG-Wohngebäudeförderung; die Staffelung nach Einkommen setzt an dieser Verteilung an.","quelle_url":"https://www.energiewechsel.de/KAENEF/Redaktion/DE/PDF-Anlagen/BEG/beg-evaluation-2022-beg-wg.pdf?__blob=publicationFile","belegstufe":"B"}]'::jsonb),
  (10915, 45, 13, null, 'Energetische Sanierung mit Aufstockung oder Erweiterung von Wohngebäuden erleichtern.', '{4502}', null, 1, 2, null, 'Aufstockung kann Sanierungen wirtschaftlicher machen; betrifft nur geeignete Gebäude, Baurecht liegt teils bei den Ländern. Wirkung kaum untersucht.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=71', null, 'offen', '2026-10-22', false, true, 'blind', '[]'::jsonb),
  (10916, 45, 13, null, 'Sanierte Gebäude einfacher als taxonomiekonform anerkennen.', '{4502}', null, 1, 1, null, 'Leichtere Taxonomie-Anerkennung könnte Sanierungskredite verbilligen; die Kriterien legt aber die EU fest, die Wirkung ist kaum untersucht.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=72', null, 'offen', '2026-10-22', false, true, 'blind', '[]'::jsonb),
  (10917, 45, 13, null, 'Anreize setzen, dass Vermieter verfügbare öffentliche Fördermittel zur Sanierung tatsächlich nutzen.', '{4502}', null, 1, 2, null, 'Setzt am Vermieter-Mieter-Dilemma an, das Sanierungen bremst; welche Anreize gemeint sind, bleibt offen, Wirkung kaum untersucht.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=72', null, 'offen', '2026-10-22', false, true, 'blind', '[]'::jsonb),
  (10918, 45, 13, null, 'Nährstoffbilanz einführen, um den Düngereinsatz gezielter zu machen und zu senken.', '{4503}', null, 2, 3, null, 'Agrarwissenschaftler empfehlen eine verlässliche betriebliche Nährstoffbilanz, um Stickstoffüberschüsse und Lachgas zu senken; ihr Nutzen hängt von Grenzwerten und Kontrolle ab und ist umstritten.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=59', 'https://www.topagrar.com/acker/news/wissenschaftler-geben-handlungsempfehlungen-fuer-klimaneutralitaet-der-landwirtschaft-12584596.html', 'gemischt', '2026-10-22', false, true, 'blind', '[{"bereich":"aufwand","richtung":"nachteil","text":"Zum Vergleich: Die Pflicht zur Stoffstrombilanz verursachte jährlich 18,1 Millionen Euro Erfüllungsaufwand; das sind nicht die Kosten dieses Wegs.","quelle_url":"https://dserver.bundestag.de/brd/2026/0251-26.pdf","belegstufe":"A"},{"bereich":"umwelt","richtung":"vorteil","text":"An landwirtschaftlich geprägten Grundwassermessstellen überschreiten 25,6 % den Nitrat-Grenzwert von 50 mg/l; eine Bilanz setzt bei den Überschüssen an.","quelle_url":"https://www.umweltbundesamt.de/daten/wasser/grundwasserbeschaffenheit","belegstufe":"A"}]'::jsonb),
  (10919, 45, 13, null, 'Verantwortung der Sektoren im Klimaschutzgesetz stärken; jedes Ministerium muss Maßnahmen umsetzen.', '{4504}', 10890, 2, 3, null, 'Der Expertenrat sah im Wegfall sektoraler Nachsteuerung eine erhöhte Gefahr der Zielverfehlung; zugleich wurden Sektorziele früher trotz Sofortprogrammen verfehlt. Per Gesetzesänderung schnell möglich.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=38', 'https://www.aerzteblatt.de/news/expertenrat-sieht-ampelplaene-zum-klimaschutzgesetz-kritisch-bb9035c9-d676-4e4e-88fe-42c073c03dc9', 'gemischt', '2026-10-22', false, true, 'blind', '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Das Sofortprogramm 2020 für den Gebäudesektor sah zusätzliche Mittel von 5,8 Mrd. Euro für die Gebäudeförderung 2021 vor; das sind nicht die Kosten dieses Wegs.","quelle_url":"https://expertenrat-klima.de/fileadmin/ERK/Pressemitteilungen_Meldungen/ERK2021_Pruefbericht-Sofortprogramm-Gebaeudesektor_Pressemitteilung.pdf","belegstufe":"A"}]'::jsonb),
  (10920, 45, 13, null, 'Bei prognostizierter längerfristiger Zielverfehlung verbindlich in den Sektoren nachsteuern.', '{4504}', 10890, 2, 3, null, 'Der Expertenrat sah im Wegfall sektoraler Nachsteuerung eine erhöhte Gefahr der Zielverfehlung; zugleich wurden Sektorziele früher trotz Sofortprogrammen verfehlt. Per Gesetzesänderung schnell möglich.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=39', 'https://www.aerzteblatt.de/news/expertenrat-sieht-ampelplaene-zum-klimaschutzgesetz-kritisch-bb9035c9-d676-4e4e-88fe-42c073c03dc9', 'gemischt', '2026-10-22', false, true, 'blind', '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Das Sofortprogramm 2020 für den Gebäudesektor sah zusätzliche Mittel von 5,8 Mrd. Euro für die Gebäudeförderung 2021 vor; das sind nicht die Kosten dieses Wegs.","quelle_url":"https://expertenrat-klima.de/fileadmin/ERK/Pressemitteilungen_Meldungen/ERK2021_Pruefbericht-Sofortprogramm-Gebaeudesektor_Pressemitteilung.pdf","belegstufe":"A"}]'::jsonb),
  (10921, 45, 14, null, 'Generelles Tempolimit auf Autobahnen ablehnen', '{4501}', 10882, 0, 3, null, 'Hält den Status quo; die laut UBA mögliche Minderung von 1,3 bis 6,6 Mio. t CO2-Äq. pro Jahr bleibt ungenutzt, die Verkehrsemissionen sinken dadurch nicht.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=41', 'https://www.umweltbundesamt.de/themen/verkehr/nachhaltige-mobilitaet/tempolimit', 'belegt', '2026-10-22', false, true, 'blind', '[{"bereich":"wirtschaft","richtung":"vorteil","text":"Ohne Tempolimit entfällt der höhere Zeitbedarf der Pkw-Fahrer bei gegebener Wegstrecke, den laut einer älteren UBA-Studie ein allgemeines Tempolimit verursacht.","quelle_url":"https://www.umweltbundesamt.de/system/files/medien/publikation/long/3136.pdf","belegstufe":"A"},{"bereich":"grundrechte","richtung":"nachteil","text":"Ohne Tempolimit bleibt die Verringerung schwerer Unfälle und der Verletzungsschwere ungenutzt, die laut Umweltbundesamt ein Tempolimit bringen kann.","quelle_url":"https://www.umweltbundesamt.de/themen/verkehr/nachhaltige-mobilitaet/tempolimit","belegstufe":"A"}]'::jsonb),
  (10922, 45, 14, null, 'Faktisches Verbrenner-Verbot ab 2035 umgehend aufheben', '{4501}', 10887, 0, 1, null, 'Flottengrenzwerte haben die Neuwagen-Emissionen nachweislich gesenkt; ihre Aufhebung bremst die Minderung. Zudem kann Deutschland die EU-Verordnung nicht allein ändern.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=40', 'https://www.eea.europa.eu/data-and-maps/indicators/average-co2-emissions-from-motor-vehicles-1/assessment', 'belegt', '2026-10-22', false, true, 'blind', '[]'::jsonb),
  (10923, 45, 14, null, 'Luftverkehrsteuer streichen und Luftsicherheitsgebühren senken', '{4501}', 10883, 0, 2, null, 'Studien zeigen, dass CO2-Preise Emissionen auch bei niedrigen Preisen senken; ihr Abbau schwächt diesen Anreiz. Rechtlich national möglich, ab dem EU-Emissionshandel für Verkehr und Wärme aber begrenzt.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=43', 'https://strathprints.strath.ac.uk/72023', 'belegt', '2026-10-22', false, true, 'blind', '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Der nationale Emissionshandel für Wärme und Verkehr brachte 2025 rund 16 Mrd. Euro für den Klima- und Transformationsfonds; das sind nicht die Kosten dieses Wegs.","quelle_url":"https://dehst.de/SharedDocs/Pressemitteilungen/DE/2026-001-Emissionshandel-21-Milliarden-Euro.html","belegstufe":"A"},{"bereich":"verteilung","richtung":"gemischt","text":"Die CO2-Bepreisung von Wärme und Verkehr belastet Haushalte 2024 mit 8,5 Mrd. Euro, Geringverdienende relativ stärker; Grundsicherung und Wohngeld gleichen das weitgehend aus.","quelle_url":"https://www.umweltbundesamt.de/system/files/medien/11850/publikationen/72_2025_cc_bf.pdf","belegstufe":"A"}]'::jsonb),
  (10924, 45, 14, null, 'Finanzierung der Straßeninfrastruktur über die Autobahn GmbH, Lkw-Maut und privates Kapital stärken', '{4501}', 10884, 0, 2, null, 'Mehr Straßenkapazität senkt keine Emissionen; Studien zu induziertem Verkehr zeigen eher Mehrverkehr, die Größe des Effekts schwankt aber stark je nach Lage und Stauniveau.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=42', null, 'gemischt', '2026-10-22', false, true, 'blind', '[{"bereich":"wirtschaft","richtung":"vorteil","text":"Straßenprojekte des Bundesverkehrswegeplans 2030 bringen laut Gesamtplanbewertung vor allem Zeitgewinne, Kosteneinsparungen und mehr Verkehrssicherheit für Verkehrsteilnehmer.","quelle_url":"https://www.bmv.de/SharedDocs/DE/Anlage/G/BVWP/bvwp-2030-kabinettsplan.pdf?__blob=publicationFile","belegstufe":"A"},{"bereich":"umwelt","richtung":"nachteil","text":"Beim Bundesverkehrswegeplan 2030 ist die Flächeninanspruchnahme der Straße je investiertem Euro fast fünfmal so groß wie bei der Schiene und zwölfmal so groß wie bei der Wasserstraße.","quelle_url":"https://www.bmv.de/SharedDocs/DE/Anlage/G/BVWP/bvwp-2030-kabinettsplan.pdf?__blob=publicationFile","belegstufe":"A"}]'::jsonb),
  (10925, 45, 14, null, 'Kappungsgrenzen bei energetischen Sanierungen lockern', '{4502}', null, 1, 3, null, 'Höhere Umlagegrenzen können Vermietern Sanierungen erleichtern, belasten aber Mieter; ob dadurch spürbar mehr saniert wird, ist umstritten.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=44', null, 'gemischt', '2026-10-22', false, true, 'blind', '[{"bereich":"verteilung","richtung":"nachteil","text":"Die Kappungsgrenze von 3 Euro je Quadratmeter in sechs Jahren soll Mieter vor sprunghaften Mieterhöhungen nach Modernisierung schützen; eine Lockerung verringert diesen Schutz.","quelle_url":"https://dserver.bundestag.de/btd/19/046/1904672.pdf","belegstufe":"A"}]'::jsonb),
  (10926, 45, 14, null, 'Gebäudewärme über einen CO2-Zertifikatehandel statt Einzelvorschriften steuern', '{4502}', null, 2, 2, null, 'CO2-Preise senken Emissionen nachweislich, im Wärmebereich reagieren Haushalte kurzfristig aber schwach; ohne begleitende Vorgaben ist das Tempo unsicher. Rahmen teils EU-Recht.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=45', 'https://strathprints.strath.ac.uk/72023', 'gemischt', '2026-10-22', false, true, 'blind', '[{"bereich":"haushalt","richtung":"vorteil","text":"Zum Vergleich: Der nationale Emissionshandel für Wärme und Verkehr brachte 2025 rund 16 Mrd. Euro für den Klima- und Transformationsfonds; das sind nicht die Kosten dieses Wegs.","quelle_url":"https://dehst.de/SharedDocs/Pressemitteilungen/DE/2026-001-Emissionshandel-21-Milliarden-Euro.html","belegstufe":"A"},{"bereich":"verteilung","richtung":"gemischt","text":"Die CO2-Bepreisung von Wärme und Verkehr belastet Haushalte 2024 mit 8,5 Mrd. Euro, Geringverdienende relativ stärker; Grundsicherung und Wohngeld gleichen das weitgehend aus.","quelle_url":"https://www.umweltbundesamt.de/system/files/medien/11850/publikationen/72_2025_cc_bf.pdf","belegstufe":"A"}]'::jsonb),
  (10927, 45, 14, null, 'Ziel der Klimaneutralität im Klimaschutzgesetz von 2045 auf das EU-Ziel 2050 verschieben', '{4504}', null, 0, 3, null, 'Ein späteres Neutralitätsziel verlangsamt die Minderung; dass nationale Ziele im Emissionshandel wenig bringen, gilt nur teilweise, da Verkehr, Gebäude und Landwirtschaft nicht voll im EU-ETS sind.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=40', null, 'offen', '2026-10-22', false, true, 'blind', '[{"bereich":"grundrechte","richtung":"nachteil","text":"Das Bundesverfassungsgericht stellte 2021 fest, dass die damaligen Vorschriften hohe Emissionsminderungslasten unumkehrbar auf Zeiträume nach 2030 verschoben.","quelle_url":"https://www.bundesverfassungsgericht.de/SharedDocs/Pressemitteilungen/DE/2021/bvg21-031.html","belegstufe":"A"}]'::jsonb),
  (10928, 45, 14, null, 'Einheitlichen europäischen Emissionshandel mit jährlich sinkender Obergrenze als Leitinstrument etablieren', '{4504}', 10891, 2, 1, null, 'Der EU-Emissionshandel hat Emissionen nachweislich gesenkt, eine Obergrenze sichert die Gesamtmenge; Sektorverfehlungen werden aber nicht behoben, und die Ausweitung hängt von EU-Entscheidungen ab.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=40', 'https://strathprints.strath.ac.uk/72023', 'belegt', '2026-10-22', false, true, 'blind', '[{"bereich":"haushalt","richtung":"vorteil","text":"Zum Vergleich: Der nationale Emissionshandel für Wärme und Verkehr, die bisher nicht im EU-Emissionshandel liegen, brachte 2025 rund 16 Mrd. Euro; das sind nicht die Erlöse dieses Wegs.","quelle_url":"https://dehst.de/SharedDocs/Pressemitteilungen/DE/2026-001-Emissionshandel-21-Milliarden-Euro.html","belegstufe":"A"},{"bereich":"verteilung","richtung":"nachteil","text":"Zum Vergleich: Die CO2-Bepreisung von Wärme und Verkehr (nationaler Emissionshandel) belastete 2024 private Haushalte mit 8,5 Mrd. Euro und Unternehmen mit 3,8 Mrd. Euro; nicht die Kosten dieses Wegs.","quelle_url":"https://www.umweltbundesamt.de/system/files/medien/11850/publikationen/72_2025_cc_bf.pdf","belegstufe":"A"}]'::jsonb),
  (10929, 45, 14, null, 'Eigenes Negativemissionsziel in das EU-Klimaziel aufnehmen', '{4504}', null, 1, 1, null, 'Ein eigenes Ziel für Negativemissionen trennt Entnahme und Minderung und verhindert Verrechnung; es hängt aber von EU-Entscheidungen ab, die Wirkung ist kaum untersucht.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=40', null, 'offen', '2026-10-22', false, true, 'blind', '[]'::jsonb),
  (10930, 45, 15, null, 'Aufhebung des Verbrennerverbots und der Flottengrenzwerte', '{4501}', 10887, 0, 1, null, 'Flottengrenzwerte haben die Neuwagen-Emissionen nachweislich gesenkt; ihre Aufhebung bremst die Minderung. Zudem kann Deutschland die EU-Verordnung nicht allein ändern.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=14', 'https://www.eea.europa.eu/data-and-maps/indicators/average-co2-emissions-from-motor-vehicles-1/assessment', 'belegt', '2026-10-22', false, true, 'blind', '[]'::jsonb),
  (10931, 45, 15, null, 'Generelles Tempolimit auf Autobahnen ablehnen', '{4501}', 10882, 0, 3, null, 'Hält den Status quo; die laut UBA mögliche Minderung von 1,3 bis 6,6 Mio. t CO2-Äq. pro Jahr bleibt ungenutzt, die Verkehrsemissionen sinken dadurch nicht.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=45', 'https://www.umweltbundesamt.de/themen/verkehr/nachhaltige-mobilitaet/tempolimit', 'belegt', '2026-10-22', false, true, 'blind', '[{"bereich":"wirtschaft","richtung":"vorteil","text":"Ohne Tempolimit entfällt der höhere Zeitbedarf der Pkw-Fahrer bei gegebener Wegstrecke, den laut einer älteren UBA-Studie ein allgemeines Tempolimit verursacht.","quelle_url":"https://www.umweltbundesamt.de/system/files/medien/publikation/long/3136.pdf","belegstufe":"A"},{"bereich":"grundrechte","richtung":"nachteil","text":"Ohne Tempolimit bleibt die Verringerung schwerer Unfälle und der Verletzungsschwere ungenutzt, die laut Umweltbundesamt ein Tempolimit bringen kann.","quelle_url":"https://www.umweltbundesamt.de/themen/verkehr/nachhaltige-mobilitaet/tempolimit","belegstufe":"A"}]'::jsonb),
  (10932, 45, 15, null, 'CO₂-bezogene Erhöhung der Lkw-Maut zurücknehmen', '{4501}', 10883, 0, 2, null, 'Studien zeigen, dass CO2-Preise Emissionen auch bei niedrigen Preisen senken; ihr Abbau schwächt diesen Anreiz. Rechtlich national möglich, ab dem EU-Emissionshandel für Verkehr und Wärme aber begrenzt.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=45', 'https://strathprints.strath.ac.uk/72023', 'belegt', '2026-10-22', false, true, 'blind', '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Der nationale Emissionshandel für Wärme und Verkehr brachte 2025 rund 16 Mrd. Euro für den Klima- und Transformationsfonds; das sind nicht die Kosten dieses Wegs.","quelle_url":"https://dehst.de/SharedDocs/Pressemitteilungen/DE/2026-001-Emissionshandel-21-Milliarden-Euro.html","belegstufe":"A"},{"bereich":"verteilung","richtung":"gemischt","text":"Die CO2-Bepreisung von Wärme und Verkehr belastet Haushalte 2024 mit 8,5 Mrd. Euro, Geringverdienende relativ stärker; Grundsicherung und Wohngeld gleichen das weitgehend aus.","quelle_url":"https://www.umweltbundesamt.de/system/files/medien/11850/publikationen/72_2025_cc_bf.pdf","belegstufe":"A"}]'::jsonb),
  (10933, 45, 15, null, 'Rollende Landstraße und Containerumschlag für Transitverbindungen etablieren', '{4501}', 10888, 1, 2, null, 'Schiene verursacht je Tonnenkilometer deutlich weniger Emissionen; trotz Förderung stagniert der Kombiverkehr aber, weil er privat rund 28 % teurer ist. Ausbau braucht Jahre.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=45', 'https://repositum.tuwien.at/handle/20.500.12708/189196?mode=full', 'gemischt', '2026-10-22', false, true, 'blind', '[{"bereich":"umwelt","richtung":"gemischt","text":"Je Tonnenkilometer stießen Güterbahnen 2022 rund 0,032 g Stickoxide aus, Lkw 0,198 g, Binnenschiffe 0,415 g; bei Luftschadstoffen hat nur die Schiene einen Vorteil.","quelle_url":"https://www.umweltbundesamt.de/system/files/medien/479/publikationen/schwere_lasten_grosse_aufgabe_ein_ziel_v5_240822_bf.pdf","belegstufe":"A"},{"bereich":"grundrechte","richtung":"nachteil","text":"Der Schienengüterverkehr ist besonders laut und fährt vor allem nachts, wenn Anwohner besonders lärmempfindlich sind (Umweltbundesamt, 2017).","quelle_url":"https://www.umweltbundesamt.de/presse/pressemitteilungen/jeder-fuenfte-deutsche-leidet-unter-schienenlaerm","belegstufe":"A"}]'::jsonb),
  (10934, 45, 15, null, 'Innerstädtische Fahrspuren und Parkraum erhalten und ausbauen', '{4501}', 10884, 0, 2, null, 'Mehr Straßenkapazität senkt keine Emissionen; Studien zu induziertem Verkehr zeigen eher Mehrverkehr, die Größe des Effekts schwankt aber stark je nach Lage und Stauniveau.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=43', null, 'gemischt', '2026-10-22', false, true, 'blind', '[{"bereich":"wirtschaft","richtung":"vorteil","text":"Straßenprojekte des Bundesverkehrswegeplans 2030 bringen laut Gesamtplanbewertung vor allem Zeitgewinne, Kosteneinsparungen und mehr Verkehrssicherheit für Verkehrsteilnehmer.","quelle_url":"https://www.bmv.de/SharedDocs/DE/Anlage/G/BVWP/bvwp-2030-kabinettsplan.pdf?__blob=publicationFile","belegstufe":"A"},{"bereich":"umwelt","richtung":"nachteil","text":"Beim Bundesverkehrswegeplan 2030 ist die Flächeninanspruchnahme der Straße je investiertem Euro fast fünfmal so groß wie bei der Schiene und zwölfmal so groß wie bei der Wasserstraße.","quelle_url":"https://www.bmv.de/SharedDocs/DE/Anlage/G/BVWP/bvwp-2030-kabinettsplan.pdf?__blob=publicationFile","belegstufe":"A"}]'::jsonb),
  (10935, 45, 15, null, 'Belastende Klimaschutzvorschriften für Seehäfen reduzieren', '{4501}', null, 0, 2, null, 'Weniger Klimaschutzvorgaben für Häfen senken keine Verkehrsemissionen, eher im Gegenteil; welche Vorgaben gemeint sind, bleibt unklar, viele beruhen auf EU-Recht.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=47', null, 'offen', '2026-10-22', false, true, 'blind', '[]'::jsonb),
  (10936, 45, 15, null, 'CO₂-Steuer abschaffen', '{4501}', 10883, 0, 2, null, 'Studien zeigen, dass CO2-Preise Emissionen auch bei niedrigen Preisen senken; ihr Abbau schwächt diesen Anreiz. Rechtlich national möglich, ab dem EU-Emissionshandel für Verkehr und Wärme aber begrenzt.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=37', 'https://strathprints.strath.ac.uk/72023', 'belegt', '2026-10-22', false, true, 'blind', '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Der nationale Emissionshandel für Wärme und Verkehr brachte 2025 rund 16 Mrd. Euro für den Klima- und Transformationsfonds; das sind nicht die Kosten dieses Wegs.","quelle_url":"https://dehst.de/SharedDocs/Pressemitteilungen/DE/2026-001-Emissionshandel-21-Milliarden-Euro.html","belegstufe":"A"},{"bereich":"verteilung","richtung":"gemischt","text":"Die CO2-Bepreisung von Wärme und Verkehr belastet Haushalte 2024 mit 8,5 Mrd. Euro, Geringverdienende relativ stärker; Grundsicherung und Wohngeld gleichen das weitgehend aus.","quelle_url":"https://www.umweltbundesamt.de/system/files/medien/11850/publikationen/72_2025_cc_bf.pdf","belegstufe":"A"}]'::jsonb),
  (10937, 45, 15, null, 'Bedarfsgerechte Düngung wieder ermöglichen und Dünge-Bürokratie begrenzen', '{4503}', 10889, 0, 2, null, 'Weniger Kontrolle der Stickstoffüberschüsse senkt kein Lachgas, sondern riskiert mehr; der Nutzen der Stoffstrombilanz für die Beratung ist allerdings umstritten. Lockerungen stoßen an die EU-Nitratrichtlinie.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=76', null, 'gemischt', '2026-10-22', false, true, 'blind', '[{"bereich":"aufwand","richtung":"vorteil","text":"Die Streichung der Stoffstrombilanz senkt den Erfüllungsaufwand um jährlich 18,1 Millionen Euro.","quelle_url":"https://dserver.bundestag.de/brd/2026/0251-26.pdf","belegstufe":"A"},{"bereich":"umwelt","richtung":"nachteil","text":"An landwirtschaftlich geprägten Grundwassermessstellen überschreiten 25,6 % den Nitrat-Grenzwert von 50 mg/l; weniger Kontrolle der Überschüsse riskiert mehr.","quelle_url":"https://www.umweltbundesamt.de/daten/wasser/grundwasserbeschaffenheit","belegstufe":"A"}]'::jsonb),
  (10938, 45, 16, null, 'Tempolimit 120 km/h auf Autobahnen und Tempo 30 innerorts (außer auf Hauptverkehrsachsen)', '{4501}', 10881, 2, 3, null, 'Laut UBA spart Tempo 130 etwa 1,3-2,0 Mio. t, Tempo 120 mit 80 außerorts rund 6,6 Mio. t CO2-Äq. pro Jahr; per Gesetz sofort umsetzbar und kostengünstig, deckt aber nur einen Teil der Verkehrslücke.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=37', 'https://www.umweltbundesamt.de/themen/verkehr/nachhaltige-mobilitaet/tempolimit', 'belegt', '2026-10-22', false, true, 'blind', '[{"bereich":"wirtschaft","richtung":"nachteil","text":"Ein allgemeines Tempolimit verursacht laut einer älteren UBA-Studie Kosten durch höheren Zeitbedarf der Pkw-Fahrer bei gegebener Wegstrecke.","quelle_url":"https://www.umweltbundesamt.de/system/files/medien/publikation/long/3136.pdf","belegstufe":"A"},{"bereich":"grundrechte","richtung":"vorteil","text":"Ein Tempolimit kann laut Umweltbundesamt die Zahl schwerer Unfälle und die Schwere der Verletzungen verringern.","quelle_url":"https://www.umweltbundesamt.de/themen/verkehr/nachhaltige-mobilitaet/tempolimit","belegstufe":"A"}]'::jsonb),
  (10939, 45, 16, null, 'Öffentliche Fahrzeugbeschaffung auf reine E-Fahrzeuge umstellen', '{4501}', null, 1, 3, null, 'Öffentliche Flotten sind klein, die direkte Minderung gering; Signal- und Markteffekte sind möglich, aber kaum untersucht.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=32', null, 'offen', '2026-10-22', false, true, 'blind', '[]'::jsonb),
  (10940, 45, 16, null, 'KfZ-Steuer neu gestalten: große und schwere Autos stärker besteuern', '{4501}', null, 1, 3, null, 'Fahrzeugsteuern nach Größe und CO2 lenken Käufe zu sparsameren Autos; Studien zum französischen Bonus-Malus finden aber teils keinen Netto-Effekt. Kfz-Steuer ist Bundessache.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=32', 'https://www.insee.fr/en/statistiques/1380983', 'gemischt', '2026-10-22', false, true, 'blind', '[]'::jsonb),
  (10941, 45, 16, null, 'Flächendeckendes bundesweites Radverkehrsnetz', '{4501}', 10885, 1, 2, null, 'Neue Radwege werden genutzt, ersetzen laut Studien aber oft nur wenige Autofahrten; ohne begleitende Maßnahmen bleibt die CO2-Wirkung klein. Bund kann über Förderprogramme beitragen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=44', null, 'gemischt', '2026-10-22', false, true, 'blind', '[{"bereich":"grundrechte","richtung":"vorteil","text":"Regelmäßiges Radfahren erhöht laut einer vom Umweltbundesamt genannten Untersuchung die Lebenserwartung um 3 bis 14 Monate.","quelle_url":"https://www.umweltbundesamt.de/themen/verkehr/nachhaltige-mobilitaet/radverkehr","belegstufe":"A"}]'::jsonb),
  (10942, 45, 16, null, 'Straßenbau auf die Sanierung des Bestands konzentrieren', '{4501}', null, 1, 3, null, 'Verzicht auf Neubau vermeidet zusätzlichen induzierten Verkehr, senkt bestehende Emissionen aber nicht; Größe des Effekts in Studien unterschiedlich. Über Haushalt und Bedarfsplan steuerbar.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=37', null, 'gemischt', '2026-10-22', false, true, 'blind', '[]'::jsonb),
  (10943, 45, 16, null, 'Flüge unter 500 Kilometern oder fünf Zugstunden verbieten', '{4501}', null, 1, 1, null, 'Das französische Kurzstreckenverbot senkte Emissionen nur wenig, auch durch Ausweichen auf andere Routen; ein Verbot braucht nach EU-Luftverkehrsrecht eine Ausnahme der Kommission.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=37', null, 'belegt', '2026-10-22', false, true, 'blind', '[{"bereich":"grundrechte","richtung":"nachteil","text":"Ein Verbot von Kurzstreckenflügen greift laut Wissenschaftlichem Dienst in Berufsfreiheit, Eigentum und Handlungsfreiheit der Fluggesellschaften ein (geprüft für Flüge unter 1.500 km).","quelle_url":"https://www.bundestag.de/resource/blob/851052/2ed2b5db2738c8a601f7d92be465ea21/WD-3-106-21-pdf-data.pdf","belegstufe":"A"}]'::jsonb),
  (10944, 45, 16, null, 'Auslaufen des Neuwagenverkaufs für Verbrenner nach der EU-Richtlinie beibehalten', '{4501}', 10886, 2, 1, null, 'EU-Flottengrenzwerte haben die Neuwagen-Emissionen 2019-2023 um rund 28 % gesenkt; die Wirkung auf den Bestand kommt aber verzögert, und die Regel hängt von EU-Entscheidungen ab.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=36', 'https://www.eea.europa.eu/data-and-maps/indicators/average-co2-emissions-from-motor-vehicles-1/assessment', 'belegt', '2026-10-22', false, true, 'blind', '[{"bereich":"umwelt","richtung":"vorteil","text":"Elektroautos stoßen laut Umweltbundesamt lokal keine Abgasschadstoffe aus und verringern die Lärmbelastung.","quelle_url":"https://www.umweltbundesamt.de/umwelttipps-fuer-den-alltag/beim-autokauf-elektroautos-bevorzugen-auf-geringen","belegstufe":"A"}]'::jsonb),
  (10945, 45, 16, null, 'Sozial gestaffelte Förderangebote für kleine E-Fahrzeuge', '{4501}', null, 1, 2, null, 'Gezielte Förderung kleiner E-Autos für Pendler und Betriebe senkt Mitnahmeeffekte gegenüber pauschalen Prämien; die CO2-Wirkung je Euro bleibt aber begrenzt, die Finanzierung ist offen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=32', null, 'gemischt', '2026-10-22', false, true, 'blind', '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Die frühere Kaufprämie Umweltbonus hatte 2016 bis 2023 bewilligte Bundesmittel von 10,17 Mrd. Euro; das sind nicht die Kosten dieses Wegs.","quelle_url":"https://technopolis-group.com/wp-content/uploads/2024/11/EB_Evaluation_Umweltbonus.pdf","belegstufe":"B"},{"bereich":"verteilung","richtung":"vorteil","text":"Beim früheren Umweltbonus hatten rund 60 % der Fördernehmenden über 4.500 Euro Haushaltsnetto im Monat; eine Staffelung nach Einkommen setzt an dieser Verteilung an.","quelle_url":"https://technopolis-group.com/wp-content/uploads/2024/11/EB_Evaluation_Umweltbonus.pdf","belegstufe":"B"}]'::jsonb),
  (10946, 45, 16, null, 'Ausbau der öffentlichen Ladeinfrastruktur', '{4501}', null, 2, 2, null, 'Studien aus Dänemark und Norwegen zeigen, dass öffentliche Ladepunkte den Umstieg auf E-Autos fördern, mit Verzögerung; Ausbau braucht Investitionen und Jahre.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=32', 'https://diposit.ub.edu/items/5a5ad497-bd95-40fc-bf98-98d5c77843d9/full', 'belegt', '2026-10-22', false, true, 'blind', '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Das Deutschlandnetz, ein Teil des Ladeinfrastruktur-Ausbaus, finanziert der Bund mit rund 2,3 Mrd. Euro; das sind nicht die Kosten dieses Wegs.","quelle_url":"https://www.bmv.de/DE/Themen/Mobilitaet/Elektromobilitaet/Deutschlandnetz/deutschlandnetz.html","belegstufe":"A"}]'::jsonb),
  (10947, 45, 16, null, 'Investitionsoffensive in energetische Sanierungen und Heizungstausch mit 25 Milliarden Euro pro Jahr', '{4502}', null, 2, 1, null, 'Sanierungsförderung senkt Gebäudeemissionen nachweislich; 25 Mrd. Euro jährlich wären deutlich mehr als bisher, die Finanzierung ist aber ungeklärt und Handwerkskapazitäten sind knapp.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=34', 'https://www.solarserver.de/2023/06/15/erste-externe-evaluation-der-beg-foerderung-vorgelegt/', 'belegt', '2026-10-22', false, true, 'blind', '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Die BEG-Wohngebäudeförderung setzte 2022 rund 12,2 Mrd. Euro Bundesmittel ein; das sind nicht die Kosten dieses Wegs.","quelle_url":"https://www.energiewechsel.de/KAENEF/Redaktion/DE/PDF-Anlagen/BEG/beg-evaluation-2022-beg-wg.pdf?__blob=publicationFile","belegstufe":"B"},{"bereich":"verteilung","richtung":"nachteil","text":"Bisher nutzen vor allem Haushalte mit über 5.000 Euro Nettoeinkommen die BEG-Wohngebäudeförderung; mit sinkendem Einkommen nimmt die Inanspruchnahme ab.","quelle_url":"https://www.energiewechsel.de/KAENEF/Redaktion/DE/PDF-Anlagen/BEG/beg-evaluation-2022-beg-wg.pdf?__blob=publicationFile","belegstufe":"B"}]'::jsonb),
  (10948, 45, 16, null, 'Immobilienkonzerne verpflichten, Sanierungspläne bei den Kommunen einzureichen', '{4502}', null, 1, 2, null, 'Sanierungspläne schaffen Planung und Druck bei großen Vermietern, verpflichten aber nicht zur Umsetzung; Wirkung kaum untersucht.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=35', null, 'offen', '2026-10-22', false, true, 'blind', '[]'::jsonb),
  (10949, 45, 16, null, 'Flächendeckende Sanierungsberatung für alle sanierungsbedürftigen Häuser', '{4502}', null, 1, 2, null, 'Beratung kann Sanierungen anstoßen; Studien finden aber nur schwache und sehr unterschiedliche Effekte, Kosten und Einsparungen entscheiden mehr. Flächendeckend braucht es viel Personal.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=34', 'https://www.rwi-essen.de/publikationen/suche/detail/heterogeneity-in-the-effect-of-home-energy-397', 'gemischt', '2026-10-22', false, true, 'blind', '[]'::jsonb),
  (10950, 45, 16, null, 'Tierhaltung auf flächengebundene Haltung umstellen und Viehbestände verringern', '{4503}', null, 2, 1, null, 'Weniger Tiere senken Methan und Gülle-Lachgas direkt; die Flächenbindung trifft aber vor allem Regionen mit hoher Viehdichte, und eine verbindliche Obergrenze stößt auf Eigentums- und Berufsfreiheit.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=42', 'https://www.umweltbundesamt.de/tags/tierbestand', 'belegt', '2026-10-22', false, true, 'blind', '[{"bereich":"umwelt","richtung":"vorteil","text":"Rund 70 Prozent der Ammoniak-Emissionen stammen aus der Tierhaltung; Ammoniak schädigt Land- und Wasserökosysteme erheblich, weniger Tiere setzen hier an.","quelle_url":"https://www.umweltbundesamt.de/themen/boden-landwirtschaft/umweltbelastungen-der-landwirtschaft/ammoniak-geruch-staub","belegstufe":"A"}]'::jsonb),
  (10951, 45, 16, null, 'Entwicklung von Düngemittelalternativen unterstützen', '{4503}', null, 1, 2, null, 'Düngemittelalternativen könnten Lachgas mindern, die Förderung von Entwicklung wirkt aber erst langfristig und unbestimmt; kaum untersucht.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=42', null, 'offen', '2026-10-22', false, true, 'blind', '[]'::jsonb),
  (10952, 45, 16, null, 'Sektorziele im Klimaschutzgesetz wieder herstellen und verbindliche Emissionsgrenzen setzen', '{4504}', 10890, 2, 3, null, 'Der Expertenrat sah im Wegfall sektoraler Nachsteuerung eine erhöhte Gefahr der Zielverfehlung; zugleich wurden Sektorziele früher trotz Sofortprogrammen verfehlt. Per Gesetzesänderung schnell möglich.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=33', 'https://www.aerzteblatt.de/news/expertenrat-sieht-ampelplaene-zum-klimaschutzgesetz-kritisch-bb9035c9-d676-4e4e-88fe-42c073c03dc9', 'gemischt', '2026-10-22', false, true, 'blind', '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Das Sofortprogramm 2020 für den Gebäudesektor sah zusätzliche Mittel von 5,8 Mrd. Euro für die Gebäudeförderung 2021 vor; das sind nicht die Kosten dieses Wegs.","quelle_url":"https://expertenrat-klima.de/fileadmin/ERK/Pressemitteilungen_Meldungen/ERK2021_Pruefbericht-Sofortprogramm-Gebaeudesektor_Pressemitteilung.pdf","belegstufe":"A"}]'::jsonb),
  (10953, 45, 17, null, 'Mehr Verkehr von der Straße auf die Schiene bringen', '{4501}', 10888, 1, 2, null, 'Schiene verursacht je Tonnenkilometer deutlich weniger Emissionen; trotz Förderung stagniert der Kombiverkehr aber, weil er privat rund 28 % teurer ist. Ausbau braucht Jahre.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=29', 'https://repositum.tuwien.at/handle/20.500.12708/189196?mode=full', 'gemischt', '2026-10-22', false, true, 'blind', '[{"bereich":"umwelt","richtung":"gemischt","text":"Je Tonnenkilometer stießen Güterbahnen 2022 rund 0,032 g Stickoxide aus, Lkw 0,198 g, Binnenschiffe 0,415 g; bei Luftschadstoffen hat nur die Schiene einen Vorteil.","quelle_url":"https://www.umweltbundesamt.de/system/files/medien/479/publikationen/schwere_lasten_grosse_aufgabe_ein_ziel_v5_240822_bf.pdf","belegstufe":"A"},{"bereich":"grundrechte","richtung":"nachteil","text":"Der Schienengüterverkehr ist besonders laut und fährt vor allem nachts, wenn Anwohner besonders lärmempfindlich sind (Umweltbundesamt, 2017).","quelle_url":"https://www.umweltbundesamt.de/presse/pressemitteilungen/jeder-fuenfte-deutsche-leidet-unter-schienenlaerm","belegstufe":"A"}]'::jsonb),
  (10954, 45, 17, null, 'Verbrennerverbot zurücknehmen', '{4501}', 10887, 0, 1, null, 'Flottengrenzwerte haben die Neuwagen-Emissionen nachweislich gesenkt; ihre Aufhebung bremst die Minderung. Zudem kann Deutschland die EU-Verordnung nicht allein ändern.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=29', 'https://www.eea.europa.eu/data-and-maps/indicators/average-co2-emissions-from-motor-vehicles-1/assessment', 'belegt', '2026-10-22', false, true, 'blind', '[]'::jsonb),
  (10955, 45, 17, null, 'Volksleasing für kleine, verbrauchsarme Fahrzeuge (auch Verbrenner unter 5 Liter)', '{4501}', null, 1, 2, null, 'Sozialleasing wie in Frankreich war stark nachgefragt und erreicht Pendler; der Einbezug von Verbrennern schwächt die Minderung, Emissionswirkung kaum evaluiert, Finanzierung offen.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=29', null, 'offen', '2026-10-22', false, true, 'blind', '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Die frühere Kaufprämie Umweltbonus hatte 2016 bis 2023 bewilligte Bundesmittel von 10,17 Mrd. Euro; das sind nicht die Kosten dieses Wegs.","quelle_url":"https://technopolis-group.com/wp-content/uploads/2024/11/EB_Evaluation_Umweltbonus.pdf","belegstufe":"B"}]'::jsonb),
  (10956, 45, 17, null, 'Förderung alternativer Kraftstoffe und Entwicklung verbrauchsarmer Verbrennermotoren', '{4501}', null, 1, 2, null, 'Sparsamere Motoren und alternative Kraftstoffe senken Emissionen etwas; laut PIK sind E-Fuels aber teuer (800-1.200 Euro/t CO2), knapp und für Pkw ineffizient, bis 2030 kaum verfügbar.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=10', 'https://publications.pik-potsdam.de/pubman/item/item_25599_8', 'belegt', '2026-10-22', false, true, 'blind', '[{"bereich":"umwelt","richtung":"nachteil","text":"E-Fuels im Pkw brauchen für dieselbe Fahrleistung etwa die drei- bis sechsfache Strommenge eines Elektro-Pkw.","quelle_url":"https://www.umweltbundesamt.de/themen/verkehr/kraftstoffe-antriebe","belegstufe":"A"}]'::jsonb),
  (10957, 45, 17, null, 'Neue Straßen bauen, wo sie nötig sind', '{4501}', 10884, 0, 2, null, 'Mehr Straßenkapazität senkt keine Emissionen; Studien zu induziertem Verkehr zeigen eher Mehrverkehr, die Größe des Effekts schwankt aber stark je nach Lage und Stauniveau.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=29', null, 'gemischt', '2026-10-22', false, true, 'blind', '[{"bereich":"wirtschaft","richtung":"vorteil","text":"Straßenprojekte des Bundesverkehrswegeplans 2030 bringen laut Gesamtplanbewertung vor allem Zeitgewinne, Kosteneinsparungen und mehr Verkehrssicherheit für Verkehrsteilnehmer.","quelle_url":"https://www.bmv.de/SharedDocs/DE/Anlage/G/BVWP/bvwp-2030-kabinettsplan.pdf?__blob=publicationFile","belegstufe":"A"},{"bereich":"umwelt","richtung":"nachteil","text":"Beim Bundesverkehrswegeplan 2030 ist die Flächeninanspruchnahme der Straße je investiertem Euro fast fünfmal so groß wie bei der Schiene und zwölfmal so groß wie bei der Wasserstraße.","quelle_url":"https://www.bmv.de/SharedDocs/DE/Anlage/G/BVWP/bvwp-2030-kabinettsplan.pdf?__blob=publicationFile","belegstufe":"A"}]'::jsonb),
  (10958, 45, 17, null, 'CO2-Preis abschaffen', '{4501,4502}', 10883, 0, 2, null, 'Studien zeigen, dass CO2-Preise Emissionen auch bei niedrigen Preisen senken; ihr Abbau schwächt diesen Anreiz. Rechtlich national möglich, ab dem EU-Emissionshandel für Verkehr und Wärme aber begrenzt.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=10', 'https://strathprints.strath.ac.uk/72023', 'belegt', '2026-10-22', false, true, 'blind', '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Der nationale Emissionshandel für Wärme und Verkehr brachte 2025 rund 16 Mrd. Euro für den Klima- und Transformationsfonds; das sind nicht die Kosten dieses Wegs.","quelle_url":"https://dehst.de/SharedDocs/Pressemitteilungen/DE/2026-001-Emissionshandel-21-Milliarden-Euro.html","belegstufe":"A"},{"bereich":"verteilung","richtung":"gemischt","text":"Die CO2-Bepreisung von Wärme und Verkehr belastet Haushalte 2024 mit 8,5 Mrd. Euro, Geringverdienende relativ stärker; Grundsicherung und Wohngeld gleichen das weitgehend aus.","quelle_url":"https://www.umweltbundesamt.de/system/files/medien/11850/publikationen/72_2025_cc_bf.pdf","belegstufe":"A"}]'::jsonb),
  (10959, 45, 17, null, 'Europäischen Emissionshandel globalisieren oder Abschaffung auf EU-Ebene anstreben', '{4504}', null, 0, 1, null, 'Der EU-Emissionshandel hat Emissionen nachweislich gesenkt; seine Abschaffung entfernt die Obergrenze, eine Globalisierung ist unrealistisch. Beides hängt von EU und anderen Staaten ab.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=11', 'https://strathprints.strath.ac.uk/72023', 'belegt', '2026-10-22', false, true, 'blind', '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Europäischer und nationaler Emissionshandel brachten in Deutschland 2025 zusammen 21,4 Mrd. Euro Einnahmen für den Klimafonds; das sind nicht die Kosten dieses Wegs.","quelle_url":"https://dehst.de/SharedDocs/Pressemitteilungen/DE/2026-001-Emissionshandel-21-Milliarden-Euro.html","belegstufe":"A"},{"bereich":"verteilung","richtung":"vorteil","text":"Zum Vergleich: Die CO2-Bepreisung von Wärme und Verkehr (nationaler Emissionshandel) belastete 2024 private Haushalte mit 8,5 Mrd. Euro; das sind nicht die Einsparungen dieses Wegs.","quelle_url":"https://www.umweltbundesamt.de/system/files/medien/11850/publikationen/72_2025_cc_bf.pdf","belegstufe":"A"}]'::jsonb);

